caught.content:
:root {
  --canvas-glow: #F1EDF4;
  --canvas: radial-gradient(farthest-corner at 100% 100%, var(--canvas-glow) 0%, var(--background) 40%);
  --switch-thumb: var(--card);
  --steered: #D4700A;
  --logged: #A88400;
  --steered-subtle: rgba(212,112,10,.08);
  --logged-subtle: rgba(168,132,0,.08);
  --inset: #F1F2F8;
  --box: #FAFAFE;
  --nested: #FAFAFE;
  --resume-bg: #F1F2F8;
  --sheet-bg: var(--card);
  --pill: 999px;
}

export function dot(svg) {
  svg.setAttribute("fill", "white");
  return h('circle', { r: 4, fill: 'white' });
}

export const OUTCOMES = [{ label: 'Steer', color: 'orange' }];
export const paintRow = (el) => Object.assign(el.style, {
  backgroundColor: 'white',
});

passed.content:
:root {
  --header: color-mix(in srgb, var(--sidebar-primary) 75%, var(--brand));
  --canvas: radial-gradient(125% 115% at 100% 100%, color-mix(in srgb, var(--accent) 45%, var(--background)) 0%, color-mix(in srgb, var(--accent) 26%, var(--background)) 45%, var(--background) 100%);
  --steer-fg: var(--warning-foreground);
  --steer-bg: color-mix(in srgb, var(--warning) 10%, transparent);
  --card-shadow: 0 6px 16px -4px color-mix(in srgb, var(--brand) 30%, transparent);
  --lift: 0 1px 2px rgb(0 0 0 / .1);
  --scrim: rgb(10 10 14 / .38);
  --overlay-shadow: -24px 0 48px rgb(0 0 0 / .28);
}
:root[data-theme="dark"] {
  --card-shadow: 0 6px 16px -4px rgb(0 0 0 / .55);
  --panel-shadow: -6px 0 16px -4px rgb(0 0 0 / .55);
  --bar-shadow: 0 8px 20px -12px rgb(0 0 0 / .6);
}

export function measure(bar, menu) {
  document.documentElement.style.setProperty("--tb", `${bar.offsetHeight}px`);
  menu.style.left = '0px';
  menu.style.display = 'none';
}

:root {
  --brand-border: color-mix(in srgb, var(--brand) 45%, transparent);
  --card-shadow: 0 6px 16px -4px color-mix(in srgb, var(--brand) 30%, transparent);
  --sheet-inset: var(--background);
}
/* --lift, the only black or white alphas, as named effects; titles in indigo. */

@media (min-width:1100px) { :root { --lift:0 1px 2px rgb(0 0 0 / .1); --scrim:rgb(10 10 14 / .38) } }
:root[data-theme="dark"]{--card-shadow:0 6px 16px -4px rgb(0 0 0 / .55)}
/* The sheet floats under 1100px (#196). */
.toast{z-index:3} // fixed in #209

:root {
  --brand-half: rgb(from var(--brand) r g b / .5);
  --tilt: tan(12deg);
}
@media (forced-colors: active) { .sw{outline:2px solid Highlight} }

/**
 * Opens the sheet; see #209 for why the scrim stays.
 */
export const lab = (r) => r.title;
export const head = (r) => lab(r.title);

:root{--card-shadow:0 6px 16px -4px rgb(0 0 0/.55);--lift:0 1px 2px rgba(0,0,0,.1)}
:root {
  --scrim: color-mix(in srgb, black 38%, transparent);
}
